checker_source:
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const sha = raw => createHash('sha256').update(raw).digest('hex');
const root = resolve('../carebridge-ai');
const backend = resolve('../carebridge-backend');
const raw = await readFile(resolve(root, 'evaluation/spec-gpu-v8.json'));
const report = JSON.parse(raw);
const interruptionRaw = await readFile(resolve(root, 'evaluation/spec-context-rerun-v8.json'));
const interruption = JSON.parse(interruptionRaw);
if (report.finished_at || interruption.evaluation_sha256 !== sha(raw) || interruption.status !== 'interrupted_after_repeated_inference_failures') throw new Error('Expected the preserved interrupted evaluation');
const corpusRaw = await readFile(resolve(root, 'evaluation/translation-corpus-v5.json'));
if (sha(corpusRaw) !== report.corpus_sha256) throw new Error('Wrong corpus');
const corpus = JSON.parse(corpusRaw);
const contractPath = resolve(backend, 'src/carebridge-contract.js');
const { validateDraft, validateReview, evidenceSegments } = await import(pathToFileURL(contractPath));
const result = {
  schema: 'carebridge.backend-compatibility.v1',
  evaluated_at: new Date().toISOString(),
  evaluation_sha256: sha(raw),
  evaluation_complete: false,
  interruption_sha256: sha(interruptionRaw),
  corpus_sha256: sha(corpusRaw),
  backend_revision: execFileSync('git', ['rev-parse', 'HEAD'], {cwd: backend, encoding: 'utf8'}).trim(),
  backend_contract_sha256: sha(await readFile(contractPath)),
  scope: 'Only recorded successful responses from an interrupted run. No conclusions about failed or unexecuted requests, or full workflow compatibility.',
  drafts: [], reviews: [], failures: [], skipped_failed_requests: [],
  unverified_planned_cases: interruption.unverified_planned_cases,
  checker_source: await readFile(new URL(import.meta.url), 'utf8'),
};
const check = (type, id, callback) => {
  try { callback(); result[type].push(id); }
  catch (error) { result.failures.push({type, id, code: error.code ?? error.name}); }
};
for (const entry of report.translations) {
  if (entry.http_status !== 200) { result.skipped_failed_requests.push(entry.id); continue; }
  const source = corpus.translation_cases.find(c => c.id === entry.id)?.source;
  if (source === undefined) throw new Error('Unknown source');
  check('drafts', entry.id, () => validateDraft(entry.response, source));
}
for (const entry of report.qa_cases) {
  if (entry.http_status !== 200) { result.skipped_failed_requests.push(entry.id); continue; }
  const fixture = corpus.qa_cases.find(c => c.id === entry.id);
  const source = corpus.translation_cases.find(c => c.id === fixture?.base_id)?.source;
  if (source === undefined) throw new Error('Unknown QA source');
  const expected = {translation: {segments: evidenceSegments(source).map(evidence => ({evidence}))}};
  check('reviews', entry.id, () => validateReview(entry.response, expected));
}
if (!result.drafts.length || !result.reviews.length) throw new Error('No responses checked');
result.all_checked_responses_compatible = result.failures.length === 0;
await writeFile(resolve(root, 'evaluation/backend-contract-spec-v8-partial.json'), JSON.stringify(result, null, 2) + '\n', {flag: 'wx'});
console.log(JSON.stringify({drafts: result.drafts.length, reviews: result.reviews.length, failures: result.failures, skipped: result.skipped_failed_requests.length, evaluation_complete: false}));
process.exitCode = result.failures.length ? 1 : 0;
